fn super_descr_get(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // The owning type is bound as `args[0]`; `obj` is required and the class
    // it is looked up on is optional.
    crate::type_methods::arity_at_least(args, "__get__", 1)?;
    crate::type_methods::arity_at_most(args, "__get__", 2)?;
    let self_ = args[0];
    let obj = args[1];
    let bound = unsafe { pyre_object::descriptor::w_super_get_obj(self_) };
    if !bound.is_null() || unsafe { pyre_object::is_none(obj) } {
        return Ok(self_);
    }
    let start = unsafe { pyre_object::descriptor::w_super_get_type(self_) };
    if start.is_null() {
        return Err(crate::PyError::type_error(
            "__get__(x) is invalid on an uninitialized instance of 'super'",
        ));
    }
    let cls = r#type(self_)
        .map(|p| p.as_ptr())
        .unwrap_or_else(|| gettypeobject(&pyre_object::descriptor::SUPER_TYPE));
    crate::call::call_function_impl_result(cls, &[start, obj])
}

/// PyPy `descriptor.py W_Super.typedef`, with Python 3.14's zero-argument
/// documentation and concrete type surface.
fn init_super_type(ns: PyObjectRef) {
    let _root_scope = pyre_object::gc_roots::push_roots();
    let ns_slot = pyre_object::gc_roots::shadow_stack_len();
    let ns = pyre_object::gc_roots::pin_root(ns);
    unsafe {
        pyre_object::w_dict_setitem_str(
            pyre_object::gc_roots::shadow_stack_get(ns_slot),
            "__doc__",
            w_str_new(
                "super() -> same as super(__class__, <first argument>)\n\
                 super(type) -> unbound super object\n\
                 super(type, obj) -> bound super object; requires isinstance(obj, type)\n\
                 super(type, type2) -> bound super object; requires issubclass(type2, type)\n\
                 Typical use to call a cooperative superclass method:\n\
                 class C(B):\n\
                     def meth(self, arg):\n\
                         super().meth(arg)\n\
                 This works for class methods too:\n\
                 class C(B):\n\
                     @classmethod\n\
                     def cmeth(cls, arg):\n\
                         super().cmeth(arg)",
            ),
        )
    };
    let new_descr = make_new_descr(super_descr_new);
    unsafe {
        crate::function::fset_func_text_signature(new_descr, w_str_new("($type, *args, **kwargs)"))
    };
    for (name, value) in [
        ("__new__", new_descr),
        (
            "__init__",
            crate::gateway::make_builtin_function_with_text_signature(
                "__init__",
                descr_init,
                "($self, /, *args, **kwargs)",
            ),
        ),
        (
            "__repr__",
            crate::gateway::make_builtin_function_with_arity_and_text_signature(
                "__repr__",
                super_descr_repr,
                1,
                "($self, /)",
            ),
        ),
        (
            "__getattribute__",
            crate::gateway::make_builtin_function_with_arity_and_text_signature(
                "__getattribute__",
                super_descr_getattribute,
                2,
                "($self, name, /)",
            ),
        ),
        (
            "__get__",
            crate::gateway::make_builtin_function_with_text_signature(
                "__get__",
                super_descr_get,
                "($self, instance, owner=None, /)",
            ),
        ),
    ] {
        unsafe { crate::__pyre_put_new!(ns_slot, name, value) };
    }
    for (name, kind, doc) in [
        (
            "__thisclass__",
            pyre_object::MEMBER_SUPER_THISCLASS,
            "the class invoking super()",
        ),
        (
            "__self__",
            pyre_object::MEMBER_SUPER_SELF,
            "the instance invoking super(); may be None",
        ),
        (
            "__self_class__",
            pyre_object::MEMBER_SUPER_SELF_CLASS,
            "the type of the instance invoking super(); may be None",
        ),
    ] {
        unsafe {
            crate::__pyre_put_new!(
                ns_slot,
                name,
                pyre_object::w_member_new_direct_with_doc(
                    kind,
                    name.to_owned(),
                    doc.to_owned(),
                    PY_NULL,
                )
            )
        };
    }
}

