// dict_new handled by dict_descr_new above (supports dict subclasses)

/// typeobject.py W_TypeObject.check_user_subclass.
///
/// ```text
/// def check_user_subclass(self, w_subtype):
///     if not isinstance(w_subtype, W_TypeObject):
///         raise TypeError("X is not a type object ('%T')", w_subtype)
///     if not w_subtype.issubtype(self):
///         raise TypeError("%N.__new__(%N): %N is not a subtype of %N", ...)
///     if self.layout.typedef is not w_subtype.layout.typedef:
///         raise TypeError("%N.__new__(%N) is not safe, use %N.__new__()", ...)
///     return w_subtype
/// ```
pub(crate) fn check_new_subtype(
    w_self: PyObjectRef,
    w_subtype: PyObjectRef,
) -> Result<(), crate::PyError> {
    if w_subtype.is_null() || !unsafe { pyre_object::is_type(w_subtype) } {
        let self_name = unsafe { pyre_object::w_type_get_name(w_self) };
        // `tp_new_wrapper` names the offending argument's type after the
        // sentence; `check_user_subclass` writes the same suffix quoted
        // (`('%T')`).  Unquoted, as `subclass_to_tag`'s own copy of this
        // refusal already writes it.
        return Err(crate::PyError::type_error(format!(
            "{}.__new__(X): X is not a type object ({})",
            self_name,
            crate::type_methods::arg_type_name(w_subtype),
        )));
    }
    if std::ptr::eq(w_subtype, w_self) {
        return Ok(());
    }
    let mro_ptr = unsafe { pyre_object::w_type_get_mro(w_subtype) };
    let is_sub = !mro_ptr.is_null()
        && unsafe { crate::baseobjspace::mro_contains((*mro_ptr).as_slice(), w_self) };
    if !is_sub {
        let self_name = unsafe { pyre_object::w_type_get_name(w_self) };
        let sub_name = unsafe { pyre_object::w_type_get_name(w_subtype) };
        return Err(crate::PyError::type_error(format!(
            "{}.__new__({}): {} is not a subtype of {}",
            self_name, sub_name, sub_name, self_name,
        )));
    }
    Ok(())
}

/// [`check_new_subtype`] plus the layout test that closes `object.__new__(dict)`.
///
/// The two are separated because only the first half applies where a
/// constructor is reached to *build* an instance: `type_call` invokes
/// `type->tp_new(type, ...)` directly rather than through the `__new__`
/// descriptor, so `tp_new_wrapper`'s layout test never sees an ordinary
/// `T(...)`.  `class VS(ValueError, StopIteration)` is what the difference
/// costs: `StopIteration`'s `value` gives VS a layout typedef that
/// `ValueError`'s does not match, where the wrapper's own criterion — the
/// `tp_new` the most-derived static base carries — finds both answering
/// `BaseException.__new__` and allows it.
pub fn check_user_subclass(
    w_self: PyObjectRef,
    w_subtype: PyObjectRef,
) -> Result<(), crate::PyError> {
    check_new_subtype(w_self, w_subtype)?;
    if std::ptr::eq(w_subtype, w_self) {
        return Ok(());
    }
    // typedef.py layout safety. The base allocator only knows
    // how to fill the parent layout; if the subtype introduces extra slots
    // (different layout typedef), allocating through it would corrupt the
    // foreign layout.
    let self_layout = unsafe { pyre_object::w_type_get_layout_ptr(w_self) };
    let sub_layout = unsafe { pyre_object::w_type_get_layout_ptr(w_subtype) };
    let self_typedef = if self_layout.is_null() {
        std::ptr::null()
    } else {
        unsafe { (*self_layout).typedef }
    };
    let sub_typedef = if sub_layout.is_null() {
        std::ptr::null()
    } else {
        unsafe { (*sub_layout).typedef }
    };
    if !std::ptr::eq(self_typedef, sub_typedef) {
        let self_name = unsafe { pyre_object::w_type_get_name(w_self) };
        let sub_name = unsafe { pyre_object::w_type_get_name(w_subtype) };
        return Err(crate::PyError::type_error(format!(
            "{}.__new__({}) is not safe, use {}.__new__()",
            self_name, sub_name, sub_name,
        )));
    }
    Ok(())
}

fn set_alloc_for_class(
    cls: PyObjectRef,
    exact_type: PyObjectRef,
    frozen: bool,
) -> Result<PyObjectRef, crate::PyError> {
    // typeobject.py allocate_instance → check_user_subclass.
    check_user_subclass(exact_type, cls)?;
    // `allocate_instance` of a subclass selects `typedef.py` `_getusercls`:
    // `W_SetObjectUser` stamped `SET_USER_TYPE` / `FROZENSET_USER_TYPE`, with
    // `w_class` installed by the allocator. An exact `set` or `frozenset`
    // stays on the base payload.
    let obj = if std::ptr::eq(cls, exact_type) {
        if frozen {
            pyre_object::w_frozenset_new()
        } else {
            pyre_object::w_set_new()
        }
    } else {
        pyre_object::w_set_user_new_empty(cls, frozen)
    };
    // objspace.py `allocate_instance` registers every freshly allocated
    // instance whose class carries `hasuserdel`.  Set/frozenset subclasses use
    // this layout-specific allocator instead of `w_instance_new`, so perform
    // the same post-allocation step after installing the real subclass.
    pyre_object::gc_hook::maybe_register_finalizer(obj);
    Ok(obj)
}

/// `set.__new__(cls, ...)` — PyPy: setobject.py W_SetObject.descr_new.
///
/// PyPy declares the inner function as `descr_new(space, w_settype,
/// __args__)`. `__args__` is the gateway sentinel for variadic positional
/// arguments, so gateway.py sets `maxargs = sys.maxint`; the body
/// ignores everything past `w_settype`. The actual argument count check
/// lives on `descr_init`, which type.__call__ runs after `__new__`.
fn set_descr_new(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let (params, kwargs) = crate::builtins::split_builtin_kwargs(args);
    let cls = params.first().copied().unwrap_or(pyre_object::PY_NULL);
    let set_type = crate::typedef::gettypeobject(&pyre_object::setobject::SET_TYPE);
    // `set.__new__` ignores its extra arguments and leaves positional-count
    // validation to `__init__`; only a plain `set(...)` whose `__init__` is not
    // overridden rejects keywords here (`_PyArg_NoKeywords`).  A subclass that
    // defines an `__init__` taking keywords must still receive them, so the
    // keyword check is skipped whenever the subtype overrides `__init__`
    // (passing 0 for `positional_extra` keeps the surplus-positional report in
    // `__init__`).
    builtinclass_new_args_check(
        "set",
        set_type,
        cls,
        0,
        crate::builtins::has_real_kwargs(kwargs),
    )?;
    set_alloc_for_class(cls, set_type, false)
}

/// `objspace/std/util.py` `builtinclass_new_args_check` — shared surplus
/// argument validation for the `__new__` of one-argument builtin classes
/// (`float`, `tuple`, `list`, `frozenset`, `itertools.cycle`).
///
/// The check is skipped when `w_subtyp` overrides `__init__`, because that
/// `__init__` consumes the surplus arguments (`space.getattr(base, '__init__')
/// is space.getattr(sub, '__init__')` — modelled here as MRO-lookup identity).
/// When it applies, a surplus positional wins over a keyword.
///
/// `positional_extra` is `len(__args__.arguments_w)` (positionals beyond the
/// single accepted argument); `has_keywords` is `__args__.keyword_names_w`.
fn builtinclass_new_args_check(
    name: &str,
    w_basetyp: PyObjectRef,
    w_subtyp: PyObjectRef,
    positional_extra: usize,
    has_keywords: bool,
) -> Result<(), crate::PyError> {
    let init_matches = w_subtyp.is_null()
        || std::ptr::eq(w_basetyp, w_subtyp)
        || unsafe {
            match (
                crate::baseobjspace::lookup_in_type(w_basetyp, "__init__"),
                crate::baseobjspace::lookup_in_type(w_subtyp, "__init__"),
            ) {
                (Some(b), Some(s)) => std::ptr::eq(b, s),
                (None, None) => true,
                _ => false,
            }
        };
    if init_matches {
        if positional_extra > 0 {
            return Err(crate::PyError::type_error(format!(
                "{name} expected at most 1 argument, got {}",
                positional_extra + 1,
            )));
        }
        if has_keywords {
            return Err(crate::PyError::type_error(format!(
                "{name}() takes no keyword arguments"
            )));
        }
    }
    Ok(())
}

/// `frozenset.__new__(cls, [iterable])` — PyPy: setobject.py W_FrozensetObject.descr_new2.
fn frozenset_descr_new(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let (args, kwargs) = crate::builtins::split_builtin_kwargs(args);
    let cls = args.first().copied().unwrap_or(pyre_object::PY_NULL);
    let frozenset_type = crate::typedef::gettypeobject(&pyre_object::setobject::FROZENSET_TYPE);
    builtinclass_new_args_check(
        "frozenset",
        frozenset_type,
        cls,
        args.len().saturating_sub(2),
        crate::builtins::has_real_kwargs(kwargs),
    )?;
    let iterable = args.get(1).copied().unwrap_or(pyre_object::PY_NULL);

    // setobject.py — reuse the argument only when the target type is
    // exactly `frozenset` and the argument's implementation class is exactly
    // `W_FrozensetObject` (`type(w_iterable) is W_FrozensetObject`); a subclass
    // instance carries `FROZENSET_USER_TYPE` and is rebuilt.
    if !iterable.is_null()
        && std::ptr::eq(cls, frozenset_type)
        && unsafe {
            pyre_object::pyobject::is_exact_type(iterable, &pyre_object::setobject::FROZENSET_TYPE)
        }
    {
        return Ok(iterable);
    }

    let mut obj = set_alloc_for_class(cls, frozenset_type, true)?;
    if !iterable.is_null() {
        pyre_object::with_roots!(obj => set_init_from_iterable(obj, iterable))?;
    }
    Ok(obj)
}

/// Fill a freshly allocated set/frozenset from `w_iterable`.
///
/// `setobject.py set_strategy_and_setdata` — the storage is set up from
/// the iterable, and a set operand (`:1619-1621`) hands its own over rather
/// than being walked: its elements hashed when they entered it.
fn set_init_from_iterable(
    w_set: PyObjectRef,
    w_iterable: PyObjectRef,
) -> Result<(), crate::PyError> {
    set_init_from_iterable_impl(w_set, w_iterable, true)
}

/// `objspace.py _uses_list_iter` / `_uses_unicode_iter`.
///
/// `__iter__` on `obj`'s type is the same descriptor as on `base_type`.
/// An exact builtin is that descriptor. A missing type object falls
/// through to iteration.
fn iterable_uses_base_iter(obj: PyObjectRef, base_type: &pyre_object::PyType) -> bool {
    let Some(obj_type) = r#type(obj) else {
        return false;
    };
    let base = gettypeobject(base_type);
    if base.is_null() {
        return false;
    }
    if std::ptr::eq(obj_type.as_ptr() as *const _, base as *const _) {
        return true;
    }
    // `lookup_in_type` can collect. `base` is live across the first call
    // and the descriptor it returns is live across the second. The pinned
    // words are read back from their slots.
    let _roots = pyre_object::gc_roots::push_roots();
    let base_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(base);
    let obj_iter_slot = {
        let obj_iter =
            unsafe { crate::baseobjspace::lookup_in_type(obj_type.as_ptr(), "__iter__") };
        match obj_iter {
            Some(found) => {
                let slot = pyre_object::gc_roots::shadow_stack_len();
                let _ = pyre_object::gc_roots::pin_root(found);
                Some(slot)
            }
            None => None,
        }
    };
    let base_iter = unsafe {
        crate::baseobjspace::lookup_in_type(
            pyre_object::gc_roots::shadow_stack_get(base_slot),
            "__iter__",
        )
    };
    match (obj_iter_slot, base_iter) {
        (Some(slot), Some(found_base)) => {
            std::ptr::eq(pyre_object::gc_roots::shadow_stack_get(slot), found_base)
        }
        _ => false,
    }
}

fn set_init_from_iterable_impl(
    w_set: PyObjectRef,
    w_iterable: PyObjectRef,
    wrap_hash_error: bool,
) -> Result<(), crate::PyError> {
    if unsafe { pyre_object::is_set_or_frozenset(w_iterable) } {
        unsafe { pyre_object::w_set_copy_storage_from(w_set, w_iterable) };
        return Ok(());
    }
    // RPython's shadowstack transformation keeps `self` live across
    // `space.listview(w_iterable)`.  `collect_iterable` can execute a long
    // generator and trigger a major collection, so mirror that generated
    // root explicitly: the set body relocates, and it must still be marked
    // live instead of being swept while Rust holds the only reference.
    let _roots = pyre_object::gc_roots::push_roots();
    let set_slot = pyre_object::gc_roots::pin_roots(&[w_set, w_iterable]);
    let iterable_slot = set_slot + 1;
    // `set_strategy_and_setdata`: `listview_bytes`, then `listview_ascii`,
    // then `listview_int`. An empty view installs that strategy.
    // `_pick_correct_strategy_unroll` stays off this path: `jit.isconstant`
    // is false outside a trace, so a miss falls through to
    // `_update_from_iterable` (the `collect_iterable` walk below).
    if unsafe {
        pyre_object::w_set_init_from_listview(
            pyre_object::gc_roots::shadow_stack_get(set_slot),
            pyre_object::gc_roots::shadow_stack_get(iterable_slot),
        )
    } {
        return Ok(());
    }
    // `listview_*` reaches a list or str subclass only through
    // `_uses_list_iter` / `_uses_unicode_iter`. Exact types were handled
    // above. `lookup_in_type` can collect, so the slots are re-read.
    if unsafe {
        let iterable = pyre_object::gc_roots::shadow_stack_get(iterable_slot);
        pyre_object::is_list(iterable)
            && !pyre_object::is_exact_list(iterable)
            && iterable_uses_base_iter(iterable, &pyre_object::LIST_TYPE)
    } && unsafe {
        pyre_object::w_set_init_from_list_storage(
            pyre_object::gc_roots::shadow_stack_get(set_slot),
            pyre_object::gc_roots::shadow_stack_get(iterable_slot),
        )
    } {
        return Ok(());
    }
    if unsafe {
        let iterable = pyre_object::gc_roots::shadow_stack_get(iterable_slot);
        pyre_object::is_str(iterable)
            && !pyre_object::is_exact_type(iterable, &pyre_object::STR_TYPE)
            && iterable_uses_base_iter(iterable, &pyre_object::STR_TYPE)
    } {
        if let Some(chars) = unsafe {
            pyre_object::w_unicode_listview_ascii(pyre_object::gc_roots::shadow_stack_get(
                iterable_slot,
            ))
        } {
            unsafe {
                pyre_object::w_set_install_ascii_items(
                    pyre_object::gc_roots::shadow_stack_get(set_slot),
                    &chars,
                );
            }
            return Ok(());
        }
    }
    // Python 3.14 `set_update_dict_lock_held`: an exact dict is walked
    // through its key table and each cached hash is handed directly to the
    // set.  This is observable when a key's `__hash__` has side effects, and
    // it is the cached-hash shape of PyPy's
    // `DictStrategy.getiteritems_with_hash`.  A dict subclass must still use
    // normal iteration because it may override `__iter__`.
    if unsafe {
        pyre_object::is_exact_type(
            pyre_object::gc_roots::shadow_stack_get(iterable_slot),
            &pyre_object::DICT_TYPE,
        )
    } {
        // `index` names an entry slot, and a tombstone sits between the live
        // ones after a delete, so the walk steps to the next live slot rather
        // than counting.  A typed strategy still ends it at the first step,
        // because `w_dict_nth_hashed_key` answers `None` for one.
        let mut index = 0usize;
        let mut copied_hashed_key = false;
        while let Some(slot) = unsafe {
            pyre_object::dictmultiobject::w_dict_next_slot(
                pyre_object::gc_roots::shadow_stack_get(iterable_slot),
                index,
            )
        } {
            let Some(key) = (unsafe {
                pyre_object::dictmultiobject::w_dict_nth_hashed_key(
                    pyre_object::gc_roots::shadow_stack_get(iterable_slot),
                    slot,
                )
            }) else {
                break;
            };
            // `setitem_with_hash` residual: the dict walk already holds the
            // cached digest, and the set insert (including a reentrant
            // `__eq__`) stays inside the leaf.
            set_setitem_with_hash_result(unsafe {
                pyre_object::w_set_setitem_with_hash(
                    pyre_object::gc_roots::shadow_stack_get(set_slot),
                    key.obj,
                    key.hash,
                )
            })?;
            copied_hashed_key = true;
            index = slot + 1;
        }
        // Empty object-shaped dicts and non-empty ones both finish here.  For
        // an empty dict the active Object/Unicode strategy is detected by a
        // zero length; typed/Empty strategies deliberately fall through.
        let strategy = unsafe {
            pyre_object::w_dict_get_strategy(pyre_object::gc_roots::shadow_stack_get(iterable_slot))
                .strategy_kind()
        };
        if copied_hashed_key
            || matches!(
                strategy,
                pyre_object::dictmultiobject::StrategyKind::Object
                    | pyre_object::dictmultiobject::StrategyKind::Unicode
            )
        {
            return Ok(());
        }
    }
    let items =
        crate::builtins::collect_iterable(pyre_object::gc_roots::shadow_stack_get(iterable_slot))?;
    let w_set = pyre_object::gc_roots::shadow_stack_get(set_slot);
    if wrap_hash_error {
        crate::builtins::builtin_set_add_items(w_set, &items)
    } else {
        crate::builtins::builtin_set_add_items_intersection(w_set, &items)
    }
}

/// `set.__init__(self, [iterable])` — PyPy: setobject.py W_SetObject.descr_init.
///
/// PyPy parses `__args__` against `init_signature = Signature(['some_iterable'])`
/// so anything beyond `(self, iterable)` raises TypeError; pyre enforces the
/// same maxargs explicitly here.
fn set_descr_init(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let set_obj = crate::type_methods::require_set_receiver(args, "__init__", false)?;
    // setobject.py `descr_init(self, space, w_iterable=None, __posonly__=None)`
    // — `iterable` is a single positional-only optional argument.  Parse the
    // gateway args against that signature (gateway interp2app `parse_into_scope`)
    // so a keyword raises the matching TypeError instead of leaking the kwargs
    // dict as the iterable: `set(iterable=[1])` → "set.__init__() got a
    // positional-only argument passed as keyword argument: 'iterable'",
    // `set(x=1)` → "set.__init__() got an unexpected keyword argument 'x'".
    let (positional, kwargs) = crate::builtins::split_builtin_kwargs(&args[1..]);
    // The argument columns live in a borrowed slice and an owned `Vec`, neither
    // of which the collector rewrites, and each keyword name allocated below
    // can move a `list` or `dict` still waiting in them.  The receiver and both
    // columns are published before the first of those allocations and read back
    // where they are used. Managed keyword names move, so each mint is pinned
    // before the next allocation.
    let _roots = pyre_object::gc_roots::push_roots();
    let n_positional = positional.len();
    let positional_base = pyre_object::gc_roots::publish_roots(positional);
    let kwargs_slot = kwargs.map(|dict| pyre_object::gc_roots::publish_roots(&[dict]));
    let set_obj_slot = pyre_object::gc_roots::publish_roots(&[set_obj]);
    pyre_object::gc_roots::normalize_roots(
        positional_base,
        n_positional + usize::from(kwargs_slot.is_some()) + 1,
    );
    let (keyword_names_w, keyword_values_base) = match kwargs_slot {
        Some(slot) => {
            let dict = pyre_object::gc_roots::shadow_stack_get(slot);
            let entries: Vec<_> = unsafe { pyre_object::w_dict_str_entries_wtf8(dict) }
                .into_iter()
                .filter(|(key, _)| key.as_str() != Ok("__pyre_kw__"))
                .collect();
            let values: Vec<PyObjectRef> = entries.iter().map(|(_, value)| *value).collect();
            let base = pyre_object::gc_roots::pin_roots(&values);
            let mut names = Vec::with_capacity(entries.len());
            for (key, _) in entries {
                let w_name = pyre_object::w_str_from_wtf8_managed(key);
                let w_name = pyre_object::gc_roots::pin_root(w_name);
                names.push(w_name);
            }
            (names, base)
        }
        None => (Vec::new(), 0),
    };
    let keywords_w: Vec<PyObjectRef> = (0..keyword_names_w.len())
        .map(|index| pyre_object::gc_roots::shadow_stack_get(keyword_values_base + index))
        .collect();
    let positional_w: Vec<PyObjectRef> = (0..n_positional)
        .map(|index| pyre_object::gc_roots::shadow_stack_get(positional_base + index))
        .collect();
    let signature = crate::gateway::Signature::new(vec!["self", "iterable"], None, None, 0, 2);
    let arguments =
        crate::argument::Arguments::with_kw(&positional_w, &keyword_names_w, &keywords_w);
    let defaults = [pyre_object::w_none()];
    let mut scope_w = vec![pyre_object::PY_NULL; signature.scope_length()];
    arguments.parse_into_scope(
        pyre_object::gc_roots::shadow_stack_get(set_obj_slot),
        &mut scope_w,
        "set.__init__",
        &signature,
        Some(&defaults),
        pyre_object::PY_NULL,
    )?;
    let iterable_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(scope_w[1]);

    // setobject.py `_initialize_set` — `w_obj.clear()` drops the
    // storage in one go, then the iterable populates it when it is not None
    // (the parsed default).  Dropping the storage allocates the empty
    // replacement, so the iterable is read back after it.
    unsafe { pyre_object::w_set_clear(pyre_object::gc_roots::shadow_stack_get(set_obj_slot)) };
    let w_iterable = pyre_object::gc_roots::shadow_stack_get(iterable_slot);
    if !w_iterable.is_null() && !unsafe { pyre_object::is_none(w_iterable) } {
        set_init_from_iterable(
            pyre_object::gc_roots::shadow_stack_get(set_obj_slot),
            w_iterable,
        )?;
    }
    Ok(pyre_object::w_none())
}

