bytearray_cmp_dunder!(bytearray_dunder_ne, Ne);
bytearray_cmp_dunder!(bytearray_dunder_lt, Lt);
bytearray_cmp_dunder!(bytearray_dunder_le, Le);
bytearray_cmp_dunder!(bytearray_dunder_gt, Gt);
