fn setlike_gateway(
    frozen: bool,
    set_gateway: crate::gateway::BuiltinCodeFn,
    frozenset_gateway: crate::gateway::BuiltinCodeFn,
) -> crate::gateway::BuiltinCodeFn {
    if frozen {
        frozenset_gateway
    } else {
        set_gateway
    }
}

