// The `|` / `&` / `-` / `^` operator slots (`nb_or` etc.) require the
// other operand to be a set/frozenset and return NotImplemented otherwise
// — unlike the `union` / `intersection` / … methods, which accept any
// iterable.  `setobject.py descr_or`/`descr_and`/`descr_sub`/`descr_xor`.
fn set_op_requires_set(args: &[pyre_object::PyObjectRef]) -> bool {
    args.len() >= 2 && !unsafe { pyre_object::is_set_or_frozenset(args[1]) }
}
fn set_op_or(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if set_op_requires_set(args) {
        return Ok(pyre_object::w_not_implemented());
    }
    set_method_union(args)
}
fn set_op_and(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if set_op_requires_set(args) {
        return Ok(pyre_object::w_not_implemented());
    }
    set_method_intersection(args)
}
fn set_op_sub(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if set_op_requires_set(args) {
        return Ok(pyre_object::w_not_implemented());
    }
    set_method_difference(args)
}
fn set_op_rsub(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if set_op_requires_set(args) {
        return Ok(pyre_object::w_not_implemented());
    }
    set_method_difference(&[args[1], args[0]])
}
fn set_op_xor(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if set_op_requires_set(args) {
        return Ok(pyre_object::w_not_implemented());
    }
    set_method_symmetric_difference(args)
}

/// `setobject.py W_BaseSetObject.descr_union` — the result starts as a copy
/// of self and every operand is merged in: a set operand through its storage
/// (`:366`), any other iterable element by element (`:368-369`).
pub(crate) fn set_method_union(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if args.is_empty() {
        return Ok(pyre_object::w_set_new());
    }
    let result = set_copy_real(args[0]);
    // `collect_iterable` runs a user `__iter__`/`__next__` and
    // `builtin_set_add_items` a user `__hash__`/`__eq__`, so the set being
    // built stays live across every operand — with two non-set operands it
    // crosses two full drains. `set_init_from_iterable_impl` pins for the same
    // reason: the set body relocates, and it still has to be marked live
    // instead of swept while Rust holds the only reference.
    // The operands go on in one phase for a second reason: `args` is the stack
    // copy the gateway built, and a minor rewrites the shadow slots rather
    // than that copy, so reading operand two out of it after operand one has
    // run a user `__hash__` answers a pre-move address.
    let _roots = pyre_object::gc_roots::push_roots();
    let operand_base = pyre_object::gc_roots::publish_roots(&args[1..]);
    let result_slot = pyre_object::gc_roots::publish_roots(&[result]);
    pyre_object::gc_roots::normalize_roots(operand_base, args.len());
    for index in 0..args.len() - 1 {
        let operand_slot = operand_base + index;
        if unsafe {
            pyre_object::is_set_or_frozenset(pyre_object::gc_roots::shadow_stack_get(operand_slot))
        } {
            unsafe {
                pyre_object::w_set_update_from_set(
                    pyre_object::gc_roots::shadow_stack_get(result_slot),
                    pyre_object::gc_roots::shadow_stack_get(operand_slot),
                )
            }
            .map_err(crate::baseobjspace::map_set_update_error)?;
        } else {
            let other_items = crate::builtins::collect_iterable(
                pyre_object::gc_roots::shadow_stack_get(operand_slot),
            )?;
            crate::builtins::builtin_set_add_items(
                pyre_object::gc_roots::shadow_stack_get(result_slot),
                &other_items,
            )?;
        }
    }
    Ok(pyre_object::gc_roots::shadow_stack_get(result_slot))
}

/// A clone of the set, keeping the digest each element was stored under.
///
/// `setobject.py W_BaseSetObject.copy_real` — "returns a clone of the
/// set; frozensets storages are also copied". The clone keeps self's class, so
/// `frozenset.union` stays a frozenset.
fn set_copy_real(w_set: pyre_object::PyObjectRef) -> pyre_object::PyObjectRef {
    let _roots = pyre_object::gc_roots::push_roots();
    let src_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_set);
    unsafe {
        let result = if pyre_object::is_frozenset(pyre_object::gc_roots::shadow_stack_get(src_slot))
        {
            pyre_object::w_frozenset_new()
        } else {
            pyre_object::w_set_new()
        };
        let result_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(result);
        pyre_object::w_set_copy_storage_from(
            pyre_object::gc_roots::shadow_stack_get(result_slot),
            pyre_object::gc_roots::shadow_stack_get(src_slot),
        );
        pyre_object::gc_roots::shadow_stack_get(result_slot)
    }
}

/// Build a set holding `w_iterable`'s elements.
///
/// `setobject.py W_SetObject._newobj` / `setobject.py
/// W_FrozensetObject._newobj` — both take ownership of the iterable's
/// elements; only the resulting class differs, and the callers here read the
/// elements back rather than the object, so one set-shaped result serves both.
///
/// Both build the set and hand the iterable to its `__init__`, so the set
/// operand branch is the one `set_init_from_iterable` already carries.
fn set_newobj(
    w_iterable: pyre_object::PyObjectRef,
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    let iterable_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_iterable);
    let set_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(pyre_object::w_set_new());
    set_init_from_iterable(
        pyre_object::gc_roots::shadow_stack_get(set_slot),
        pyre_object::gc_roots::shadow_stack_get(iterable_slot),
    )?;
    Ok(pyre_object::gc_roots::shadow_stack_get(set_slot))
}

fn set_newobj_intersection(
    w_iterable: pyre_object::PyObjectRef,
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    let iterable_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_iterable);
    let set_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(pyre_object::w_set_new());
    set_init_from_iterable_impl(
        pyre_object::gc_roots::shadow_stack_get(set_slot),
        pyre_object::gc_roots::shadow_stack_get(iterable_slot),
        false,
    )?;
    Ok(pyre_object::gc_roots::shadow_stack_get(set_slot))
}

/// The operand as a set: itself when it already is one, otherwise a set built
/// from it.
///
/// `setobject.py descr_difference_update`, `:499-503
/// descr_symmetric_difference_update` and `:312-316 descr_intersection` all
/// open with this branch — a set operand is handed to the storage-level
/// operation as it stands, and only a non-set is walked and hashed into one.
fn set_operand_as_set(
    w_other: pyre_object::PyObjectRef,
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if unsafe { pyre_object::is_set_or_frozenset(w_other) } {
        return Ok(w_other);
    }
    set_newobj(w_other)
}

/// Keep only the elements the two sides share.
///
/// `setobject.py AbstractUnwrappedSetStrategy.intersect_update` swaps the
/// operands when self is the longer, and `setobject.py _intersect_base`
/// swaps again on the way through, so either way the shorter side is walked
/// and it is that side's objects the result holds. Equal elements can be
/// distinct objects, so which side is walked is observable; a tie walks self.
///
/// `setobject.py _intersect_unwrapped` walks the storage as
/// `(key, keyhash)` pairs and probes the other side with `contains_with_hash`,
/// so the elements are neither re-hashed nor handed to a user `__hash__` again;
/// only `eq_w` runs, from the bucket probes.
fn set_intersect_update(
    w_set: pyre_object::PyObjectRef,
    w_other: pyre_object::PyObjectRef,
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    unsafe {
        let _roots = pyre_object::gc_roots::push_roots();
        let set_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(w_set);
        let other_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(w_other);
        let (keep_slot, probe_slot) =
            if pyre_object::w_set_len(pyre_object::gc_roots::shadow_stack_get(set_slot))
                > pyre_object::w_set_len(pyre_object::gc_roots::shadow_stack_get(other_slot))
            {
                (other_slot, set_slot)
            } else {
                (set_slot, other_slot)
            };
        // `result` has no referrer yet, and the `eq_w` a bucket probe runs is a
        // collection point that would sweep it.  The operand bodies relocate,
        // so each walk step reloads them; each key is re-read from the table
        // the collector rewrites rather than carried across that probe.
        let result_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(pyre_object::w_set_new());
        let mut i = 0;
        while let Some(slot) =
            pyre_object::w_set_next_slot(pyre_object::gc_roots::shadow_stack_get(keep_slot), i)
        {
            let keep = pyre_object::gc_roots::shadow_stack_get(keep_slot);
            let Some(key) = pyre_object::w_set_key_at(keep, slot) else {
                break;
            };
            if pyre_object::w_set_contains_key_checked(
                pyre_object::gc_roots::shadow_stack_get(probe_slot),
                key,
            )
            .map_err(|_| crate::baseobjspace::take_pending_hash_error())?
            {
                let keep = pyre_object::gc_roots::shadow_stack_get(keep_slot);
                let Some(key) = pyre_object::w_set_key_at(keep, slot) else {
                    break;
                };
                pyre_object::w_set_insert_key_checked(
                    pyre_object::gc_roots::shadow_stack_get(result_slot),
                    key,
                )
                .map_err(crate::baseobjspace::map_set_update_error)?;
            }
            i = slot + 1;
        }
        Ok(pyre_object::gc_roots::shadow_stack_get(result_slot))
    }
}

/// `setobject.py W_BaseSetObject.descr_intersection` — the shortest
/// operand seeds the result and the rest are intersected into it. Length is
/// measured on the operands as given, before any is turned into a set, so an
/// operand whose length cannot be taken (a generator) never seeds and a list
/// with duplicates is measured longer than the set it becomes. That measure
/// disagreeing with the set lengths is what leaves work for the swap in
/// `set_intersect_update`.
pub(crate) fn set_method_intersection(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if args.is_empty() {
        return Ok(pyre_object::w_set_new());
    }
    // An operand column copied into a plain `Vec` is not something the
    // collector rewrites, and both loops below run Python for every entry —
    // `len_w` calls a user `__len__`, the drain calls `__iter__` — so a `list`
    // or `dict` operand waiting its turn would be intersected at a pre-move
    // address.  The column is published once and every operand is read back
    // from its slot when its turn comes; the seed swap becomes an index
    // permutation over those slots rather than a move inside a `Vec`.
    let operand_roots = pyre_object::gc_roots::push_roots();
    let operand_base = pyre_object::gc_roots::pin_roots(args);

    // find smallest set in the operands to reduce comparisons
    let mut startindex = 0usize;
    let mut startlength: i64 = -1;
    for i in 0..args.len() {
        let length = match crate::baseobjspace::len_w(operand_roots.get(operand_base + i)) {
            Ok(length) => length,
            Err(e)
                if e.kind == crate::PyErrorKind::TypeError
                    || e.kind == crate::PyErrorKind::AttributeError =>
            {
                continue;
            }
            Err(e) => return Err(e),
        };
        if startlength == -1 || length < startlength {
            startindex = i;
            startlength = length;
        }
    }
    let operand = |position: usize| {
        let index = match position {
            0 => startindex,
            p if p == startindex => 0,
            p => p,
        };
        operand_roots.get(operand_base + index)
    };

    // `setobject.py` — the seed and every operand become sets, and a
    // set operand is intersected as it stands rather than rebuilt.
    // Every set here is freshly minted with no referrer: the seed, each operand
    // `set_newobj_intersection` builds out of a non-set, and the accumulator
    // each `set_intersect_update` hands back — whose own root scope ends when it
    // returns.  The bodies relocate, so each value is re-pinned and the next
    // call reloads it; they also have to survive the iterable drain and the
    // `__eq__` a bucket probe runs.
    let _roots = pyre_object::gc_roots::push_roots();
    let mut result_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(set_newobj_intersection(operand(0))?);
    for position in 1..args.len() {
        let w_other = operand(position);
        let other_slot = pyre_object::gc_roots::shadow_stack_len();
        if unsafe { pyre_object::is_set_or_frozenset(w_other) } {
            let _ = pyre_object::gc_roots::pin_root(w_other);
        } else {
            let _ = pyre_object::gc_roots::pin_root(set_newobj_intersection(w_other)?);
        };
        let next = set_intersect_update(
            pyre_object::gc_roots::shadow_stack_get(result_slot),
            pyre_object::gc_roots::shadow_stack_get(other_slot),
        )?;
        result_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(next);
    }
    unsafe {
        if pyre_object::is_frozenset(operand_roots.get(operand_base)) {
            let w_frozenset = pyre_object::w_frozenset_new();
            let w_frozenset = pyre_object::gc_roots::pin_root(w_frozenset);
            pyre_object::w_set_copy_storage_from(
                w_frozenset,
                pyre_object::gc_roots::shadow_stack_get(result_slot),
            );
            return Ok(w_frozenset);
        }
    }
    Ok(pyre_object::gc_roots::shadow_stack_get(result_slot))
}

/// `setobject.py W_BaseSetObject.descr_difference` — a copy of self with
/// `descr_difference_update` run over it.
pub(crate) fn set_method_difference(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if args.is_empty() {
        return Ok(pyre_object::w_set_new());
    }
    // The copy has no referrer yet and the update below drains each operand
    // through Python. Publish the receiver and every operand first so the
    // copy cannot move a tail argument.
    let _roots = pyre_object::gc_roots::push_roots();
    let base = pyre_object::gc_roots::pin_roots(args);
    let result = set_copy_real(pyre_object::gc_roots::shadow_stack_get(base));
    let result_slot = pyre_object::gc_roots::shadow_stack_len();
    let result = pyre_object::gc_roots::pin_root(result);
    let mut update_args: Vec<pyre_object::PyObjectRef> = vec![result];
    for i in 1..args.len() {
        update_args.push(pyre_object::gc_roots::shadow_stack_get(base + i));
    }
    set_method_difference_update(&update_args)?;
    // The update ran Python, so the copy may have moved: answer the slot.
    Ok(pyre_object::gc_roots::shadow_stack_get(result_slot))
}

pub(crate) fn set_method_symmetric_difference(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    let name = if unsafe { pyre_object::is_frozenset(args[0]) } {
        "frozenset.symmetric_difference"
    } else {
        "set.symmetric_difference"
    };
    crate::type_methods::arity_exact(args, name, 1)?;
    // `setobject.py symmetric_difference` wraps the computed storage
    // in a set of self's class.  Each set below is freshly minted with no
    // referrer and outlives a further allocation, so each takes the
    // lifetime pin the intersection path takes; the bodies relocate, so
    // later uses reload the slot.
    // The receiver needs the pin too, not just the minted sets: unlike
    // `set_method_union` and `set_method_difference`, which copy it before any
    // Python runs, this one drains the operand first and only then walks the
    // receiver — and `COMPARE_OP` popped it off the value stack.
    // Both go on the stack as one slice: a `pin_root` per value ends each
    // publication in a forwarding query, itself a safepoint, so the operand
    // would be published at its pre-query address.  The operand is also the
    // movable one — any iterable, a list included — so the conversion reads it
    // off its slot.
    let _roots = pyre_object::gc_roots::push_roots();
    let receiver_slot = pyre_object::gc_roots::pin_roots(&[args[0], args[1]]);
    let w_other_as_set =
        set_operand_as_set(pyre_object::gc_roots::shadow_stack_get(receiver_slot + 1))?;
    let other_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_other_as_set);
    let w_new = set_symmetric_difference_storage(
        pyre_object::gc_roots::shadow_stack_get(receiver_slot),
        pyre_object::gc_roots::shadow_stack_get(other_slot),
    )?;
    let new_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_new);
    unsafe {
        if pyre_object::is_frozenset(pyre_object::gc_roots::shadow_stack_get(receiver_slot)) {
            let w_frozenset = pyre_object::w_frozenset_new();
            let w_frozenset = pyre_object::gc_roots::pin_root(w_frozenset);
            pyre_object::w_set_copy_storage_from(
                w_frozenset,
                pyre_object::gc_roots::shadow_stack_get(new_slot),
            );
            return Ok(w_frozenset);
        }
    }
    Ok(pyre_object::gc_roots::shadow_stack_get(new_slot))
}

/// Set rich comparisons accept only another set/frozenset.  The named
/// `issubset`/`issuperset` methods below deliberately have a different shape:
/// they materialize any iterable.  PyPy keeps these as distinct descr_* entry
/// points (`setobject.py`), so do not route the operator slots through
/// `set_method_le`/`set_method_ge`.
fn set_descr_eq(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if args.len() < 2 || !unsafe { pyre_object::is_set_or_frozenset(args[1]) } {
        return Ok(pyre_object::w_not_implemented());
    }
    set_method_eq(args)
}

fn set_descr_ne(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    let w_eq = set_descr_eq(args)?;
    if unsafe { pyre_object::is_not_implemented(w_eq) } {
        return Ok(w_eq);
    }
    Ok(pyre_object::w_bool_from(!unsafe {
        pyre_object::w_bool_get_value(w_eq)
    }))
}

fn set_descr_le(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if args.len() < 2 || !unsafe { pyre_object::is_set_or_frozenset(args[1]) } {
        return Ok(pyre_object::w_not_implemented());
    }
    unsafe {
        if pyre_object::w_set_len(args[0]) > pyre_object::w_set_len(args[1]) {
            return Ok(pyre_object::w_bool_from(false));
        }
    }
    Ok(pyre_object::w_bool_from(set_is_subset_of(
        args[0], args[1],
    )?))
}

fn set_descr_lt(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if args.len() < 2 || !unsafe { pyre_object::is_set_or_frozenset(args[1]) } {
        return Ok(pyre_object::w_not_implemented());
    }
    unsafe {
        if pyre_object::w_set_len(args[0]) >= pyre_object::w_set_len(args[1]) {
            return Ok(pyre_object::w_bool_from(false));
        }
    }
    Ok(pyre_object::w_bool_from(set_is_subset_of(
        args[0], args[1],
    )?))
}

fn set_descr_ge(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if args.len() < 2 || !unsafe { pyre_object::is_set_or_frozenset(args[1]) } {
        return Ok(pyre_object::w_not_implemented());
    }
    unsafe {
        if pyre_object::w_set_len(args[0]) < pyre_object::w_set_len(args[1]) {
            return Ok(pyre_object::w_bool_from(false));
        }
    }
    Ok(pyre_object::w_bool_from(set_is_subset_of(
        args[1], args[0],
    )?))
}

fn set_descr_gt(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if args.len() < 2 || !unsafe { pyre_object::is_set_or_frozenset(args[1]) } {
        return Ok(pyre_object::w_not_implemented());
    }
    unsafe {
        if pyre_object::w_set_len(args[0]) <= pyre_object::w_set_len(args[1]) {
            return Ok(pyre_object::w_bool_from(false));
        }
    }
    Ok(pyre_object::w_bool_from(set_is_subset_of(
        args[1], args[0],
    )?))
}

fn set_method_eq(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if args.len() < 2 {
        return Ok(pyre_object::w_bool_from(false));
    }
    unsafe {
        if !pyre_object::is_set_or_frozenset(args[1]) {
            return Ok(pyre_object::w_bool_from(false));
        }
        if pyre_object::w_set_len(args[0]) != pyre_object::w_set_len(args[1]) {
            return Ok(pyre_object::w_bool_from(false));
        }
    }
    Ok(pyre_object::w_bool_from(set_is_subset_of(
        args[0], args[1],
    )?))
}

/// Whether the two sets share no element. Both must be sets.
///
/// `setobject.py _isdisjoint_unwrapped` walks one storage as
/// `(key, keyhash)` pairs and probes the other with `contains_with_hash`;
/// `:1214-1215 isdisjoint` walks the shorter side.
fn set_is_disjoint_from(
    w_set: pyre_object::PyObjectRef,
    w_other: pyre_object::PyObjectRef,
) -> Result<bool, crate::PyError> {
    unsafe {
        let _roots = pyre_object::gc_roots::push_roots();
        let set_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(w_set);
        let other_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(w_other);
        let (walk_slot, probe_slot) =
            if pyre_object::w_set_len(pyre_object::gc_roots::shadow_stack_get(set_slot))
                > pyre_object::w_set_len(pyre_object::gc_roots::shadow_stack_get(other_slot))
            {
                (other_slot, set_slot)
            } else {
                (set_slot, other_slot)
            };
        let mut i = 0;
        while let Some(slot) =
            pyre_object::w_set_next_slot(pyre_object::gc_roots::shadow_stack_get(walk_slot), i)
        {
            let walk = pyre_object::gc_roots::shadow_stack_get(walk_slot);
            let Some(key) = pyre_object::w_set_key_at(walk, slot) else {
                break;
            };
            if pyre_object::w_set_contains_key_checked(
                pyre_object::gc_roots::shadow_stack_get(probe_slot),
                key,
            )
            .map_err(|_| crate::baseobjspace::take_pending_hash_error())?
            {
                return Ok(false);
            }
            i = slot + 1;
        }
        Ok(true)
    }
}

/// Whether every element of `w_set` is in `w_other`. Both must be sets.
///
/// `setobject.py _issubset_unwrapped` walks self's storage as
/// `(key, keyhash)` pairs and probes with `contains_with_hash`, so a comparison
/// re-hashes nothing.
pub(crate) fn set_is_subset_of(
    w_set: pyre_object::PyObjectRef,
    w_other: pyre_object::PyObjectRef,
) -> Result<bool, crate::PyError> {
    // The probe compares with the digest each element was stored under, so the
    // walk hashes nothing — but a bucket match still runs the elements'
    // `__eq__`, which is a collection point.  Both operands are pinned here
    // because a caller cannot be relied on to hold them: `COMPARE_OP` pops
    // them, and `set_operand_as_set` hands over a set it has just minted.  The
    // bodies relocate, so each step reloads them; `key` is re-read from the
    // table after the probe.
    let _roots = pyre_object::gc_roots::push_roots();
    let set_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_set);
    let other_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_other);
    unsafe {
        let mut i = 0;
        while let Some(slot) =
            pyre_object::w_set_next_slot(pyre_object::gc_roots::shadow_stack_get(set_slot), i)
        {
            let w_set = pyre_object::gc_roots::shadow_stack_get(set_slot);
            let Some(key) = pyre_object::w_set_key_at(w_set, slot) else {
                break;
            };
            if !pyre_object::w_set_contains_key_checked(
                pyre_object::gc_roots::shadow_stack_get(other_slot),
                key,
            )
            .map_err(|_| crate::baseobjspace::take_pending_hash_error())?
            {
                return Ok(false);
            }
            i = slot + 1;
        }
        Ok(true)
    }
}

fn set_method_le(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    let name = if unsafe { pyre_object::is_frozenset(args[0]) } {
        "frozenset.issubset"
    } else {
        "set.issubset"
    };
    crate::type_methods::arity_exact(args, name, 1)?;
    let mut w_self = args[0];
    let w_other = args[1];
    let w_other_as_set = pyre_object::with_roots!(w_self => set_operand_as_set(w_other))?;
    Ok(pyre_object::w_bool_from(set_is_subset_of(
        w_self,
        w_other_as_set,
    )?))
}

fn set_method_ge(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    let name = if unsafe { pyre_object::is_frozenset(args[0]) } {
        "frozenset.issuperset"
    } else {
        "set.issuperset"
    };
    crate::type_methods::arity_exact(args, name, 1)?;
    // `setobject.py descr_issuperset` — the operand becomes a set and
    // the subset test runs the other way round.
    let mut w_self = args[0];
    let w_other = args[1];
    let w_other_as_set = pyre_object::with_roots!(w_self => set_operand_as_set(w_other))?;
    Ok(pyre_object::w_bool_from(set_is_subset_of(
        w_other_as_set,
        w_self,
    )?))
}

// `setobject.py` W_BaseSetObject mutating helpers — shared by the
// `*_update` methods (which accept any iterable) and the in-place operator
// slots (which pre-filter their operand to a set/frozenset).
fn set_method_update(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if args.is_empty() {
        return Ok(pyre_object::w_none());
    }
    // Rooted as `set_method_union`, except that the operands merge into
    // `args[0]` itself: a raw Rust slice the collector cannot see either.
    let _roots = pyre_object::gc_roots::push_roots();
    let set_slot = pyre_object::gc_roots::pin_roots(args);
    let operand_base = set_slot + 1;
    // `setobject.py _descr_update` — a set operand's storage merges in
    // as it stands; only another iterable is walked and hashed element by
    // element.
    for index in 0..args.len() - 1 {
        let operand_slot = operand_base + index;
        if unsafe {
            pyre_object::is_set_or_frozenset(pyre_object::gc_roots::shadow_stack_get(operand_slot))
        } {
            unsafe {
                pyre_object::w_set_update_from_set(
                    pyre_object::gc_roots::shadow_stack_get(set_slot),
                    pyre_object::gc_roots::shadow_stack_get(operand_slot),
                )
            }
            .map_err(crate::baseobjspace::map_set_update_error)?;
        } else {
            let other_items = crate::builtins::collect_iterable(
                pyre_object::gc_roots::shadow_stack_get(operand_slot),
            )?;
            crate::builtins::builtin_set_add_items(
                pyre_object::gc_roots::shadow_stack_get(set_slot),
                &other_items,
            )?;
        }
    }
    Ok(pyre_object::w_none())
}

/// `setobject.py W_BaseSetObject.descr_difference_update` — a non-set
/// operand is turned into a set first, so it is hashed and deduped before
/// anything is removed and a later unhashable element leaves self untouched.
/// A set operand is used as it stands (`:392-393`).
fn set_method_difference_update(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if args.is_empty() {
        return Ok(pyre_object::w_none());
    }
    // Rooted as `set_method_update`: turning an operand into a set hashes its
    // elements, so `args` is read once here and every later use comes off the
    // root stack.
    let _roots = pyre_object::gc_roots::push_roots();
    let set_slot = pyre_object::gc_roots::pin_roots(args);
    for index in 1..args.len() {
        let w_other_as_set =
            set_operand_as_set(pyre_object::gc_roots::shadow_stack_get(set_slot + index))?;
        unsafe {
            pyre_object::w_set_difference_update_from_set(
                pyre_object::gc_roots::shadow_stack_get(set_slot),
                w_other_as_set,
            )
        }
        .map_err(crate::baseobjspace::map_set_update_error)?;
    }
    Ok(pyre_object::w_none())
}

/// `setobject.py W_SetObject.descr_intersection_update` — the result of
/// `descr_intersection` replaces self's storage wholesale, so self keeps the
/// surviving objects of whichever operand seeded that result rather than its
/// own.
fn set_method_intersection_update(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    if args.is_empty() {
        return Ok(pyre_object::w_none());
    }
    // Every other operand becomes a set, hashing its elements, so an
    // unhashable one raises even when self is empty and there is nothing
    // left to compare against.
    // `set_method_intersection` collects. `args` is a raw slice, so self is
    // re-read from the shadow stack before the storage swap
    // (`setobject.py` `descr_intersection_update`).
    let _roots = pyre_object::gc_roots::push_roots();
    let self_slot = pyre_object::gc_roots::pin_roots(args);
    let mut operands = Vec::with_capacity(args.len());
    for index in 0..args.len() {
        operands.push(pyre_object::gc_roots::shadow_stack_get(self_slot + index));
    }
    let result = set_method_intersection(&operands)?;
    let result_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(result);
    unsafe {
        pyre_object::w_set_copy_storage_from(
            pyre_object::gc_roots::shadow_stack_get(self_slot),
            pyre_object::gc_roots::shadow_stack_get(result_slot),
        )
    };
    Ok(pyre_object::w_none())
}

/// `setobject.py W_SetObject.descr_symmetric_difference_update` — a
/// non-set operand is turned into a set first, so it is hashed and deduped
/// before anything is toggled: a later unhashable element leaves self
/// untouched, and a duplicate toggles once rather than twice.
fn set_method_symmetric_difference_update(
    args: &[pyre_object::PyObjectRef],
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    crate::type_methods::arity_exact(args, "symmetric_difference_update", 1)?;
    let _roots = pyre_object::gc_roots::push_roots();
    let base = pyre_object::gc_roots::pin_roots(args);
    let w_other_as_set = set_operand_as_set(pyre_object::gc_roots::shadow_stack_get(base + 1))?;
    let other_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_other_as_set);
    let w_new = set_symmetric_difference_storage(
        pyre_object::gc_roots::shadow_stack_get(base),
        pyre_object::gc_roots::shadow_stack_get(other_slot),
    )?;
    let new_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_new);
    // `setobject.py` — the computed storage replaces self's.
    unsafe {
        pyre_object::w_set_copy_storage_from(
            pyre_object::gc_roots::shadow_stack_get(base),
            pyre_object::gc_roots::shadow_stack_get(new_slot),
        )
    };
    Ok(pyre_object::w_none())
}

/// Map a `w_set_setitem_with_hash` result: `-1` is the pending `__eq__` /
/// `__hash__` exception, `-2` a table resized by a callback.
fn set_setitem_with_hash_result(rc: i64) -> Result<(), crate::PyError> {
    match rc {
        0 => Ok(()),
        -2 => Err(crate::PyError::runtime_error(
            "Set changed size during iteration",
        )),
        _ => Err(crate::baseobjspace::take_pending_hash_error()),
    }
}

/// One `iterkeys_with_hash` pass of
/// `ObjectSetStrategy._symmetric_difference_unwrapped`: keys of `walk` that
/// `contains_with_hash` misses in `probe` are placed in `d_new`.
fn symmetric_difference_one_side(
    walk_slot: usize,
    probe_slot: usize,
    d_new_slot: usize,
) -> Result<(), crate::PyError> {
    unsafe {
        let mut index = 0usize;
        loop {
            let walk = pyre_object::gc_roots::shadow_stack_get(walk_slot);
            if index >= pyre_object::w_set_num_ever_used_items(walk) {
                break;
            }
            let key = pyre_object::w_set_iterkey_at(walk, index);
            if !key.is_null() {
                let keyhash = pyre_object::w_set_iterkey_hash_at(walk, index);
                let probe = pyre_object::gc_roots::shadow_stack_get(probe_slot);
                let present = pyre_object::w_set_contains_with_hash(probe, key, keyhash);
                if present < 0 {
                    return Err(crate::baseobjspace::take_pending_hash_error());
                }
                if present == 0 {
                    let walk = pyre_object::gc_roots::shadow_stack_get(walk_slot);
                    let key = pyre_object::w_set_iterkey_at(walk, index);
                    if key.is_null() {
                        break;
                    }
                    let keyhash = pyre_object::w_set_iterkey_hash_at(walk, index);
                    let d_new = pyre_object::gc_roots::shadow_stack_get(d_new_slot);
                    set_setitem_with_hash_result(pyre_object::w_set_setitem_with_hash(
                        d_new, key, keyhash,
                    ))?;
                }
            }
            index += 1;
        }
        Ok(())
    }
}

/// The elements on exactly one of the two sides, as a set.
///
/// `setobject.py _symmetric_difference_unwrapped` — each side is
/// walked as `(key, keyhash)` pairs and probed against the other with
/// `contains_with_hash`, and what survives is placed under the digest it
/// already carries. Membership is decided by the table, so an element only
/// counts as present when it lands in the same bucket and compares equal; a
/// bare `eq_w` scan over the elements would instead call two objects the same
/// element on `__eq__` alone, and place them where their hashes never meet.
///
/// Walked as `iterkeys_with_hash` (`setobject.py`
/// `ObjectSetStrategy._symmetric_difference_unwrapped`): each live slot yields
/// a key and the digest it was stored under, `contains_with_hash` probes the
/// other side, and a miss is placed with `setitem_with_hash`. Those three are
/// residual leaves, so this loop stays traced and only the per-key table
/// operations cross a residual boundary. The two operands and `d_new` are only
/// reachable from this frame's Rust locals; a probe `eq_w` that triggers a
/// collection would sweep an unrooted body and relocate a rooted one, so each
/// is pinned and reloaded. Each key is re-read from the table the collector
/// rewrites rather
/// than carried across the `eq_w` a bucket probe can run.
fn set_symmetric_difference_storage(
    w_set: pyre_object::PyObjectRef,
    w_other: pyre_object::PyObjectRef,
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    unsafe {
        let _roots = pyre_object::gc_roots::push_roots();
        let set_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(w_set);
        let other_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(w_other);
        let d_new_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(pyre_object::w_set_new());
        // Two passes, the order in `_symmetric_difference_unwrapped`: the
        // other side first, then this side. A pair array would be a
        // classdef-less instance whose `__pos_1` getattr phase A cannot lower.
        symmetric_difference_one_side(other_slot, set_slot, d_new_slot)?;
        symmetric_difference_one_side(set_slot, other_slot, d_new_slot)?;
        Ok(pyre_object::gc_roots::shadow_stack_get(d_new_slot))
    }
}

/// `descr_inplace_*` returns self after the update. The update collects, and
/// `args` is a raw slice the collector does not rewrite, so the returned word
/// is the shadow-stack slot (`setobject.py` `descr_inplace_or` returns `self`).
fn set_inplace_self(
    args: &[pyre_object::PyObjectRef],
    update: fn(&[pyre_object::PyObjectRef]) -> Result<pyre_object::PyObjectRef, crate::PyError>,
) -> Result<pyre_object::PyObjectRef, crate::PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    let self_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(args[0]);
    update(args)?;
    Ok(pyre_object::gc_roots::shadow_stack_get(self_slot))
}

// `setobject.py` W_SetObject.descr_inplace_sub / _and / _or / _xor — a
// non-set/-frozenset operand yields NotImplemented; otherwise mutate self
// through the matching update helper and return self.
