/// The receiver check every unbound `line_iterator` / `positions_iterator`
/// method needs: each reads its payload at its own layout, so an unchecked
/// receiver reaches those accessors as type confusion.
fn require_line_table_iterator(
    args: &[PyObjectRef],
    name: &str,
    type_name: &str,
    is_receiver: unsafe fn(PyObjectRef) -> bool,
) -> Result<PyObjectRef, crate::PyError> {
    let Some(&receiver) = args.first() else {
        return Err(crate::PyError::type_error(format!(
            "descriptor '{name}' of '{type_name}' object needs an argument"
        )));
    };
    if !unsafe { is_receiver(receiver) } {
        let received = crate::baseobjspace::object_functionstr_type_name(receiver);
        return Err(crate::PyError::type_error(format!(
            "descriptor '{name}' requires a '{type_name}' object but received a '{received}'"
        )));
    }
    Ok(receiver)
}

fn init_set_iterator_type(ns: PyObjectRef) {
    let _root_scope = pyre_object::gc_roots::push_roots();
    let ns_slot = pyre_object::gc_roots::shadow_stack_len();
    let ns = pyre_object::gc_roots::pin_root(ns);
    unsafe { crate::__pyre_put_new!(ns_slot, "__doc__", pyre_object::w_none()) };
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__iter__",
            make_builtin_function_with_arity("__iter__", set_iter_self, 1)
        )
    };
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__next__",
            make_builtin_function_with_arity("__next__", set_iter_next, 1)
        )
    };
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__length_hint__",
            make_builtin_function_with_arity("__length_hint__", set_iter_length_hint, 1)
        )
    };
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__reduce__",
            make_builtin_function_with_arity("__reduce__", set_iter_reduce, 1)
        )
    };
    set_iterator_text_signatures(
        pyre_object::gc_roots::shadow_stack_get(ns_slot),
        &[
            ("__iter__", "($self, /)"),
            ("__next__", "($self, /)"),
            ("__length_hint__", "($self, /)"),
            ("__reduce__", "($self, /)"),
        ],
    );
}

fn generator_frame(obj: PyObjectRef) -> *mut crate::pyframe::PyFrame {
    unsafe { pyre_object::generator::w_generator_get_frame(obj) as *mut crate::pyframe::PyFrame }
}

fn generator_kind_repr(obj: PyObjectRef, kind: &str) -> crate::PyResult {
    // `generator_name_value` allocates the fallback name. Take the id after
    // that, from the rooted generator, and read the name from its slot into
    // the formatted buffer before the result string is allocated.
    let _roots = pyre_object::gc_roots::push_roots();
    let obj_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(obj);
    let name = generator_name_value(pyre_object::gc_roots::shadow_stack_get(obj_slot), true)?;
    let name_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(name);
    let addr = crate::display::repr_gc_addr(pyre_object::gc_roots::shadow_stack_get(obj_slot));
    let name = pyre_object::gc_roots::shadow_stack_get(name_slot);
    Ok(w_str_from_wtf8_managed(crate::display::wtf8_format!(
        "<",
        kind,
        " object ",
        unsafe { pyre_object::w_str_get_wtf8(name) },
        format!(" at {addr}>"),
    )))
}

fn generator_descr_repr(args: &[PyObjectRef]) -> crate::PyResult {
    generator_kind_repr(args[0], "generator")
}

fn coroutine_descr_repr(args: &[PyObjectRef]) -> crate::PyResult {
    generator_kind_repr(args[0], "coroutine")
}

fn async_generator_descr_repr(args: &[PyObjectRef]) -> crate::PyResult {
    generator_kind_repr(args[0], "async_generator")
}

fn generator_name_value(obj: PyObjectRef, qualname: bool) -> crate::PyResult {
    let override_value = unsafe {
        if qualname {
            pyre_object::generator::w_generator_get_qualname(obj)
        } else {
            pyre_object::generator::w_generator_get_name(obj)
        }
    };
    if !override_value.is_null() {
        return Ok(override_value);
    }
    // generator.py `get_name` / `get_qualname`: both fallback paths
    // read the immutable generator-owned `pycode`, never the frame (which is
    // cleared on exhaustion).  `_qualname is None` delegates to `get_name`.
    let pycode = unsafe { pyre_object::generator::w_generator_get_pycode(obj) };
    if pycode.is_null() || unsafe { pyre_object::is_none(pycode) } {
        return Ok(w_str_new_managed("<finished>"));
    }
    let code_ptr = unsafe { crate::pycode::w_code_get_ptr(pycode) } as *const crate::CodeObject;
    if code_ptr.is_null() {
        return Ok(w_str_new_managed("<finished>"));
    }
    // generator.py `get_name`: the fallback is `pycode.co_name`.
    Ok(unsafe { crate::pycode::w_code_name_obj(pycode) })
}

fn generator_getter_for(args: &[PyObjectRef], field: usize, kind: u8) -> crate::PyResult {
    let obj = args.get(1).copied().unwrap_or(PY_NULL);
    let matches = unsafe {
        match kind {
            0 => pyre_object::generator::is_generator(obj),
            1 => pyre_object::generator::is_coroutine(obj),
            _ => pyre_object::generator::is_async_generator(obj),
        }
    };
    if !matches {
        return Err(crate::PyError::type_error(format!(
            "descriptor is for '{}'",
            match kind {
                0 => "generator",
                1 => "coroutine",
                _ => "async_generator",
            }
        )));
    }
    let frame = generator_frame(obj);
    Ok(match field {
        0 => w_bool_from(unsafe { pyre_object::generator::w_generator_is_running(obj) }),
        1 => w_bool_from(unsafe {
            pyre_object::generator::w_generator_is_started(obj)
                && !pyre_object::generator::w_generator_is_running(obj)
                && !pyre_object::generator::w_generator_is_exhausted(obj)
        }),
        2 => {
            if frame.is_null() || unsafe { pyre_object::generator::w_generator_is_exhausted(obj) } {
                w_none()
            } else {
                frame as PyObjectRef
            }
        }
        // generator.py:387 / :464 `interp_attrproperty_w('pycode')` reads the
        // generator-owned immutable field, not the possibly-cleared frame.
        3 => unsafe { pyre_object::generator::w_generator_get_pycode(obj) },
        4 => {
            if frame.is_null() {
                w_none()
            } else {
                let delegated = unsafe { (*frame).w_yielding_from };
                if delegated.is_null() {
                    w_none()
                } else {
                    delegated
                }
            }
        }
        5 => return generator_name_value(obj, false),
        _ => return generator_name_value(obj, true),
    })
}

fn generator_getter(args: &[PyObjectRef], field: usize) -> crate::PyResult {
    generator_getter_for(args, field, 0)
}

fn coroutine_getter(args: &[PyObjectRef], field: usize) -> crate::PyResult {
    generator_getter_for(args, field, 1)
}

fn async_generator_getter(args: &[PyObjectRef], field: usize) -> crate::PyResult {
    generator_getter_for(args, field, 2)
}

