// ── itertools.count / itertools.repeat TypeDefs ─────────────────────
// PyPy: pypy/module/itertools/interp_itertools.py W_Count.typedef and
// W_Repeat.typedef.  Python 3.14 deliberately omits the old PyPy
// `__reduce__` entries, so these two concrete types are not picklable.

fn itertools_constructor_scope(
    args: &[PyObjectRef],
    fn_name: &str,
    names: Vec<&'static str>,
    defaults: &[PyObjectRef],
) -> Result<(PyObjectRef, Vec<PyObjectRef>), crate::PyError> {
    itertools_constructor_scope_kwonly(args, fn_name, names, defaults, 0)
}

fn itertools_constructor_scope_kwonly(
    args: &[PyObjectRef],
    fn_name: &str,
    names: Vec<&'static str>,
    defaults: &[PyObjectRef],
    kwonlyargcount: usize,
) -> Result<(PyObjectRef, Vec<PyObjectRef>), crate::PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    let (positional, kwargs) = crate::builtins::split_builtin_kwargs(args);
    let cls = positional.first().copied().unwrap_or(PY_NULL);
    let positional = positional.get(1..).unwrap_or(&[]);
    // The positional slice, the requested class, and the defaults are not
    // slots the collector rewrites, and the names allocated below can move
    // any of them.  All three are published before the first of those
    // allocations and read back where they are used. Managed keyword names
    // move, so each mint is pinned before the next allocation.
    let n_positional = positional.len();
    let n_defaults = defaults.len();
    let positional_default_count = n_defaults.saturating_sub(kwonlyargcount);
    let positional_base = pyre_object::gc_roots::publish_roots(positional);
    let cls_slot = pyre_object::gc_roots::publish_roots(&[cls]);
    let defaults_base = pyre_object::gc_roots::publish_roots(defaults);
    pyre_object::gc_roots::normalize_roots(positional_base, n_positional + 1 + n_defaults);
    let (keyword_names_w, keyword_values_base) = match kwargs {
        Some(dict) => {
            let entries: Vec<_> = unsafe { pyre_object::w_dict_str_entries_wtf8(dict) }
                .into_iter()
                .filter(|(key, _)| key.as_str() != Ok("__pyre_kw__"))
                .collect();
            let values: Vec<PyObjectRef> = entries.iter().map(|(_, value)| *value).collect();
            let base = pyre_object::gc_roots::pin_roots(&values);
            let mut names = Vec::with_capacity(entries.len());
            for (key, _) in entries {
                let w_name = pyre_object::w_str_from_wtf8_managed(key);
                let w_name = pyre_object::gc_roots::pin_root(w_name);
                names.push(w_name);
            }
            (names, base)
        }
        None => (Vec::new(), 0),
    };
    let kw_defs_slot = if kwonlyargcount == 0 {
        None
    } else {
        let w_kw_defs = pyre_object::w_dict_new();
        let kw_defs_slot = pyre_object::gc_roots::pin_roots(&[w_kw_defs]);
        let kw_names_start = names.len() - kwonlyargcount;
        for index in 0..kwonlyargcount {
            unsafe {
                pyre_object::w_dict_setitem_str_no_proxy(
                    pyre_object::gc_roots::shadow_stack_get(kw_defs_slot),
                    names[kw_names_start + index],
                    pyre_object::gc_roots::shadow_stack_get(
                        defaults_base + positional_default_count + index,
                    ),
                )
            };
        }
        Some(kw_defs_slot)
    };
    let signature = crate::gateway::Signature::new(names, None, None, kwonlyargcount, 0);
    let keywords_w: Vec<PyObjectRef> = (0..keyword_names_w.len())
        .map(|index| pyre_object::gc_roots::shadow_stack_get(keyword_values_base + index))
        .collect();
    let positional_w: Vec<PyObjectRef> = (0..n_positional)
        .map(|index| pyre_object::gc_roots::shadow_stack_get(positional_base + index))
        .collect();
    let arguments =
        crate::argument::Arguments::with_kw(&positional_w, &keyword_names_w, &keywords_w);
    let mut scope_w = vec![PY_NULL; signature.scope_length()];
    let mut defaults_w = vec![PY_NULL; positional_default_count];
    pyre_object::gc_roots::shadow_stack_copy_range(defaults_base, &mut defaults_w);
    let w_kw_defs = match kw_defs_slot {
        Some(slot) => pyre_object::gc_roots::shadow_stack_get(slot),
        None => PY_NULL,
    };
    arguments.parse_into_scope(
        PY_NULL,
        &mut scope_w,
        fn_name,
        &signature,
        Some(&defaults_w),
        w_kw_defs,
    )?;
    Ok((pyre_object::gc_roots::shadow_stack_get(cls_slot), scope_w))
}

fn count_check_number(obj: PyObjectRef) -> Result<(), crate::PyError> {
    // interp_itertools.py `check_number`, with CPython 3.14's public error
    // wording (`a number is required`) in place of PyPy 3.11's older text.
    let has_int = unsafe { crate::baseobjspace::lookup(obj, "__int__") }.is_some();
    let has_float = unsafe { crate::baseobjspace::lookup(obj, "__float__") }.is_some();
    let complex_type = gettypefor(&pyre_object::COMPLEX_TYPE).map_or(PY_NULL, |p| p.as_ptr());
    if !has_int
        && !has_float
        && (complex_type.is_null()
            || !unsafe { crate::baseobjspace::isinstance_w(obj, complex_type) })
    {
        return Err(crate::PyError::type_error("a number is required"));
    }
    Ok(())
}

fn count_descr_new(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // W_Count___new__(space, w_subtype, w_start=0, w_step=1).
    let _roots = pyre_object::gc_roots::push_roots();
    let w_zero = w_int_new(0);
    let w_zero = pyre_object::gc_roots::pin_root(w_zero);
    let w_one = w_int_new(1);
    let w_one = pyre_object::gc_roots::pin_root(w_one);
    let (cls, scope) =
        itertools_constructor_scope(args, "count", vec!["start", "step"], &[w_zero, w_one])?;
    let w_start = scope[0];
    let w_step = scope[1];
    count_check_number(w_start)?;
    count_check_number(w_step)?;
    let exact =
        gettypefor(&pyre_object::interp_itertools::COUNT_TYPE).map_or(PY_NULL, |p| p.as_ptr());
    check_user_subclass(exact, cls)?;
    let w_subtype = if std::ptr::eq(cls, exact) {
        PY_NULL
    } else {
        cls
    };
    Ok(pyre_object::interp_itertools::w_count_new(
        w_start, w_step, w_subtype,
    ))
}

fn count_single_argument(w_step: PyObjectRef) -> Result<bool, crate::PyError> {
    // W_Count.single_argument: isinstance(step, int) and step == 1.
    let int_type = gettypefor(&pyre_object::INT_TYPE).map_or(PY_NULL, |p| p.as_ptr());
    if int_type.is_null() || !unsafe { crate::baseobjspace::isinstance_w(w_step, int_type) } {
        return Ok(false);
    }
    let _roots = pyre_object::gc_roots::push_roots();
    let step_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_step);
    let one = w_int_new(1);
    crate::baseobjspace::eq_w(pyre_object::gc_roots::shadow_stack_get(step_slot), one)
}

fn count_descr_repr(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let obj = args.first().copied().unwrap_or(PY_NULL);
    let cls = r#type(obj).map_or(PY_NULL, |p| p.as_ptr());
    let full_name = unsafe { pyre_object::w_type_get_name(cls) };
    let cls_name = full_name.rsplit('.').next().unwrap_or(full_name);
    let w_c = unsafe { pyre_object::interp_itertools::w_count_get_c(obj) };
    let mut w_step = unsafe { pyre_object::interp_itertools::w_count_get_step(obj) };
    let c = unsafe { pyre_object::with_roots!(w_step => crate::display::py_repr_wtf8(w_c))? };
    let text = if pyre_object::with_roots!(w_step => count_single_argument(w_step))? {
        crate::display::wtf8_format!(cls_name, "(", c, ")")
    } else {
        let step = unsafe { crate::display::py_repr_wtf8(w_step)? };
        crate::display::wtf8_format!(cls_name, "(", c, ", ", step, ")")
    };
    Ok(w_str_from_wtf8_managed(text))
}

/// [3.14-spec] CPython `count_slots` publishes `Py_tp_getattro`, while PyPy's
/// `W_Count.typedef` inherits the same lookup from `object`.  Keep the lookup
/// in the object space and expose only the additional observable type-dict
/// entry; `W_Count`'s storage and every other operation remain PyPy-owned.
fn count_descr_getattribute(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let obj = args.first().copied().unwrap_or(PY_NULL);
    let name_obj = args.get(1).copied().unwrap_or(PY_NULL);
    if !unsafe { pyre_object::is_str(name_obj) } {
        return Err(crate::PyError::type_error("attribute name must be string"));
    }
    let name = unsafe { pyre_object::w_str_get_wtf8(name_obj) };
    match name.as_str() {
        Ok(name) => crate::baseobjspace::object_getattribute(obj, name),
        Err(_) => unsafe {
            crate::baseobjspace::object_getattribute_surrogate(obj, name_obj, name)
        },
    }
}

fn init_count_type(ns: PyObjectRef) {
    let _root_scope = pyre_object::gc_roots::push_roots();
    let ns_slot = pyre_object::gc_roots::shadow_stack_len();
    let ns = pyre_object::gc_roots::pin_root(ns);
    // Source order follows `W_Count.typedef`: constructor, iteration, repr,
    // terminal doc. `__reduce__` is the one removed Python-3.14 surface entry;
    // `count_slots`' observable `__getattribute__` entry is inserted before
    // the terminal doc without changing the PyPy-owned operation order.
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__new__",
            make_new_descr_with_doc(
                count_descr_new,
                "Create and return a new object.  See help(type) for accurate signature.",
            )
        )
    };
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__iter__",
            crate::gateway::make_slot_wrapper_with_arity_and_doc(
                "__iter__",
                crate::baseobjspace::iter_self_method,
                1,
                "Implement iter(self).",
            )
        )
    };
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__next__",
            crate::gateway::make_slot_wrapper_with_arity_and_doc(
                "__next__",
                crate::baseobjspace::iter_next_method,
                1,
                "Implement next(self).",
            )
        )
    };
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__repr__",
            crate::gateway::make_slot_wrapper_with_arity_and_doc(
                "__repr__",
                count_descr_repr,
                1,
                "Return repr(self).",
            )
        )
    };
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__getattribute__",
            crate::gateway::make_slot_wrapper_with_arity_and_doc(
                "__getattribute__",
                count_descr_getattribute,
                2,
                "Return getattr(self, name).",
            )
        )
    };
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__doc__",
            w_str_new(
                "Return a count object whose .__next__() method returns consecutive values.\n\nEquivalent to:\n    def count(firstval=0, step=1):\n        x = firstval\n        while 1:\n            yield x\n            x += step",
            )
        )
    };
    for (name, text_signature) in [
        ("__new__", "($type, *args, **kwargs)"),
        ("__iter__", "($self, /)"),
        ("__next__", "($self, /)"),
        ("__repr__", "($self, /)"),
        ("__getattribute__", "($self, name, /)"),
    ] {
        set_type_callable_text_signature(
            pyre_object::gc_roots::shadow_stack_get(ns_slot),
            name,
            text_signature,
        );
    }
}

fn repeat_descr_new(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    // W_Repeat___new__(space, w_subtype, w_object, w_times=None).  A null
    // default represents a missing `times`; an explicit Python None still
    // passes through `space.index_w` and raises TypeError, as in 3.14.
    let (mut cls, scope) =
        itertools_constructor_scope(args, "repeat", vec!["object", "times"], &[PY_NULL])?;
    let mut w_obj = scope[0];
    let w_times = scope[1];
    let times = if w_times.is_null() {
        None
    } else {
        Some(pyre_object::with_roots!(cls, w_obj => crate::builtins::space_index_w(w_times))?)
    };
    let exact =
        gettypefor(&pyre_object::interp_itertools::REPEAT_TYPE).map_or(PY_NULL, |p| p.as_ptr());
    check_user_subclass(exact, cls)?;
    let w_subtype = if std::ptr::eq(cls, exact) {
        PY_NULL
    } else {
        cls
    };
    Ok(pyre_object::interp_itertools::w_repeat_new(
        w_obj, times, w_subtype,
    ))
}

fn repeat_descr_length_hint(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let obj = args.first().copied().unwrap_or(PY_NULL);
    if unsafe { pyre_object::interp_itertools::w_repeat_get_counting(obj) } {
        Ok(w_int_new(unsafe {
            pyre_object::interp_itertools::w_repeat_get_count(obj)
        }))
    } else {
        // PyPy 3.11 returned NotImplemented; Python 3.14 raises directly.
        Err(crate::PyError::type_error("len() of unsized object"))
    }
}

fn repeat_descr_repr(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let mut obj = args.first().copied().unwrap_or(PY_NULL);
    let cls = r#type(obj).map_or(PY_NULL, |p| p.as_ptr());
    let full_name = unsafe { pyre_object::w_type_get_name(cls) };
    let cls_name = full_name.rsplit('.').next().unwrap_or(full_name);
    let w_obj = unsafe { pyre_object::interp_itertools::w_repeat_get_obj(obj) };
    let objrepr = unsafe { pyre_object::with_roots!(obj => crate::display::py_repr_wtf8(w_obj))? };
    let text = if unsafe { pyre_object::interp_itertools::w_repeat_get_counting(obj) } {
        let count = unsafe { pyre_object::interp_itertools::w_repeat_get_count(obj) };
        crate::display::wtf8_format!(cls_name, "(", objrepr, format!(", {count})"))
    } else {
        crate::display::wtf8_format!(cls_name, "(", objrepr, ")")
    };
    Ok(w_str_from_wtf8_managed(text))
}

/// [3.14-spec] CPython `repeat_slots` publishes `Py_tp_getattro`, while PyPy's
/// `W_Repeat.typedef` inherits object lookup.  Expose that observable type-dict
/// entry through the same object-space operation without changing PyPy's
/// repeat storage, iteration, or source order.
fn init_repeat_type(ns: PyObjectRef) {
    let _root_scope = pyre_object::gc_roots::push_roots();
    let ns_slot = pyre_object::gc_roots::shadow_stack_len();
    let ns = pyre_object::gc_roots::pin_root(ns);
    // Source order follows PyPy `W_Repeat.typedef`: constructor, iteration,
    // length hint, next, repr, and terminal doc.  CPython 3.14's observable
    // `__getattribute__` slot entry is the sole inserted operation.
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__new__",
            make_new_descr_with_doc(
                repeat_descr_new,
                "Create and return a new object.  See help(type) for accurate signature.",
            )
        )
    };
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__iter__",
            crate::gateway::make_slot_wrapper_with_arity_and_doc(
                "__iter__",
                crate::baseobjspace::iter_self_method,
                1,
                "Implement iter(self).",
            )
        )
    };
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__length_hint__",
            crate::gateway::make_method_descriptor_with_arity_and_doc(
                "__length_hint__",
                repeat_descr_length_hint,
                1,
                "Private method returning an estimate of len(list(it)).",
            )
        )
    };
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__next__",
            crate::gateway::make_slot_wrapper_with_arity_and_doc(
                "__next__",
                crate::baseobjspace::iter_next_method,
                1,
                "Implement next(self).",
            )
        )
    };
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__repr__",
            crate::gateway::make_slot_wrapper_with_arity_and_doc(
                "__repr__",
                repeat_descr_repr,
                1,
                "Return repr(self).",
            )
        )
    };
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__getattribute__",
            crate::gateway::make_slot_wrapper_with_arity_and_doc(
                "__getattribute__",
                count_descr_getattribute,
                2,
                "Return getattr(self, name).",
            )
        )
    };
    unsafe {
        crate::__pyre_put_new!(
            ns_slot,
            "__doc__",
            w_str_new(
                "repeat(object [,times]) -> create an iterator which returns the object\nfor the specified number of times.  If not specified, returns the object\nendlessly.",
            )
        )
    };
    for (name, text_signature) in [
        ("__new__", "($type, *args, **kwargs)"),
        ("__iter__", "($self, /)"),
        ("__length_hint__", "($self, /)"),
        ("__next__", "($self, /)"),
        ("__repr__", "($self, /)"),
        ("__getattribute__", "($self, name, /)"),
    ] {
        set_type_callable_text_signature(
            pyre_object::gc_roots::shadow_stack_get(ns_slot),
            name,
            text_signature,
        );
    }
}

// ── itertools predicate iterator TypeDefs ────────────────────────────
// PyPy W_TakeWhile / W_DropWhile / W_FilterFalse.  Python 3.14 keeps the
// constructor/iterator shape but no longer exposes PyPy 3.11's pickle state
// methods on these concrete types.

fn itertools_twoarg_new(
    args: &[PyObjectRef],
    exact_type: PyObjectRef,
    name: &str,
) -> Result<(PyObjectRef, PyObjectRef, PyObjectRef), crate::PyError> {
    // interp_itertools.py W_Twoarg__new__, kept in source order.
    let (positional, kwargs) = crate::builtins::split_builtin_kwargs(args);
    let cls = positional.first().copied().unwrap_or(PY_NULL);
    let args_w = positional.get(1..).unwrap_or(&[]);
    let init_matches = std::ptr::eq(cls, exact_type)
        || unsafe {
            match (
                crate::baseobjspace::lookup_in_type(cls, "__init__"),
                crate::baseobjspace::lookup_in_type(exact_type, "__init__"),
            ) {
                (Some(sub), Some(base)) => std::ptr::eq(sub, base),
                (None, None) => true,
                _ => false,
            }
        };
    if init_matches && crate::builtins::has_real_kwargs(kwargs) {
        return Err(crate::PyError::type_error(format!(
            "{name}() takes no keyword arguments"
        )));
    }
    if args_w.len() != 2 {
        return Err(crate::PyError::type_error(format!(
            "{name} expected 2 arguments, got {}",
            args_w.len()
        )));
    }
    Ok((cls, args_w[0], args_w[1]))
}

fn takewhile_descr_new(args: &[PyObjectRef]) -> Result<PyObjectRef, crate::PyError> {
    let mut exact =
        gettypefor(&pyre_object::interp_itertools::TAKEWHILE_TYPE).map_or(PY_NULL, |p| p.as_ptr());
    let (mut cls, mut predicate, iterable) = itertools_twoarg_new(args, exact, "takewhile")?;
    let iterator =
        pyre_object::with_roots!(cls, exact, predicate => crate::baseobjspace::iter(iterable))?;
    check_user_subclass(exact, cls)?;
    let w_subtype = if std::ptr::eq(cls, exact) {
        PY_NULL
    } else {
        cls
    };
    Ok(pyre_object::interp_itertools::w_takewhile_new(
        predicate, iterator, w_subtype,
    ))
}

