    /// `init_typeobjects` publishes iterator TypeDefs through
    /// `Cache.getorbuild` (`object_space().gettypeobject`). That acquire
    /// must not drop the GIL unless the cache RLock is actually contended:
    /// a sibling that already holds the GIL and then waits on
    /// `TYPEOBJECT_CACHE` would otherwise deadlock with the initializer
    /// trying to take the GIL back.
    ///
    /// Fresh process: `TYPEOBJECT_CACHE` is process-wide, and a prior
    /// `#[test]` would close the window.
    #[test]
    fn init_typeobjects_does_not_deadlock_against_a_gil_holder() {
        use std::sync::Barrier;

        if std::env::var_os("PYRE_TYPEOBJECT_DEADLOCK_CHILD").is_none() {
            let exe = std::env::current_exe().expect("test harness path");
            let mut child = std::process::Command::new(exe)
                .arg("typedef::tests::init_typeobjects_does_not_deadlock_against_a_gil_holder")
                .arg("--exact")
                .env("PYRE_TYPEOBJECT_DEADLOCK_CHILD", "1")
                .env("RUST_TEST_THREADS", "1")
                .spawn()
                .expect("spawn deadlock-scenario child");
            let start = std::time::Instant::now();
            loop {
                match child.try_wait().expect("wait deadlock-scenario child") {
                    Some(status) => {
                        assert!(
                            status.success(),
                            "child init_typeobjects deadlock scenario failed: {status}"
                        );
                        return;
                    }
                    None if start.elapsed() > std::time::Duration::from_secs(30) => {
                        let _ = child.kill();
                        panic!(
                            "init_typeobjects deadlocked against a GIL-holding waiter \
                             (Cache.getorbuild released the GIL inside TYPEOBJECT_CACHE.get_or_init)"
                        );
                    }
                    None => std::thread::sleep(std::time::Duration::from_millis(20)),
                }
            }
        }

        let barrier = Barrier::new(2);
        std::thread::scope(|scope| {
            scope.spawn(|| {
                // Take the GIL before the initializer starts, then wait on
                // TYPEOBJECT_CACHE while still holding it — the Windows CI
                // hang: install_hash_hook then get_or_init on a waiter.
                crate::module::thread::ensure_runtime_thread();
                barrier.wait();
                crate::typedef::init_typeobjects();
            });
            scope.spawn(|| {
                barrier.wait();
                crate::typedef::init_typeobjects();
            });
        });
    }

    /// The contended half of the test above: when another thread holds the
    /// `Cache.getorbuild` lock, the initializer does drop the GIL while it
    /// waits for that lock, and a sibling can take the GIL in that window.
    /// The sibling must not then wait for the initializer while it keeps the
    /// GIL, or the initializer can never take the GIL back.
    ///
    /// Fresh process, for the same reason as the test above.
    #[test]
    fn init_typeobjects_does_not_deadlock_when_the_cache_lock_is_contended() {
        use std::sync::mpsc;

        if std::env::var_os("PYRE_TYPEOBJECT_CONTENDED_DEADLOCK_CHILD").is_none() {
            let exe = std::env::current_exe().expect("test harness path");
            let mut child = std::process::Command::new(exe)
                .arg("typedef::tests::init_typeobjects_does_not_deadlock_when_the_cache_lock_is_contended")
                .arg("--exact")
                .env("PYRE_TYPEOBJECT_CONTENDED_DEADLOCK_CHILD", "1")
                .env("RUST_TEST_THREADS", "1")
                .spawn()
                .expect("spawn contended deadlock-scenario child");
            let start = std::time::Instant::now();
            loop {
                match child
                    .try_wait()
                    .expect("wait contended deadlock-scenario child")
                {
                    Some(status) => {
                        assert!(
                            status.success(),
                            "child contended init_typeobjects scenario failed: {status}"
                        );
                        return;
                    }
                    None if start.elapsed() > std::time::Duration::from_secs(60) => {
                        let _ = child.kill();
                        panic!(
                            "init_typeobjects deadlocked against a GIL-holding waiter \
                             while the Cache.getorbuild lock was contended"
                        );
                    }
                    None => std::thread::sleep(std::time::Duration::from_millis(20)),
                }
            }
        }

        /// Holds the process-wide `Cache.getorbuild` lock from inside
        /// `_build` until told to return.
        struct HoldLock {
            entered: mpsc::SyncSender<()>,
            release: std::sync::Mutex<mpsc::Receiver<()>>,
        }
        impl majit_rlib::cache::CacheBuilder<usize, usize> for HoldLock {
            type Error = ();

            fn _build(&self, key: &usize) -> Result<usize, majit_rlib::cache::CacheError<()>> {
                self.entered.send(()).unwrap();
                self.release.lock().unwrap().recv().unwrap();
                Ok(*key)
            }
        }

        let (entered_tx, entered_rx) = mpsc::sync_channel(1);
        let (release_tx, release_rx) = mpsc::channel();
        let holder = HoldLock {
            entered: entered_tx,
            release: std::sync::Mutex::new(release_rx),
        };
        let cache = majit_rlib::cache::Cache::<usize, usize>::new();
        std::thread::scope(|scope| {
            // Not a runtime thread: it holds the cache lock without the GIL.
            scope.spawn(|| cache.getorbuild(1, &holder).unwrap());
            entered_rx.recv().unwrap();
            // Takes the GIL first, then drops it inside
            // `TYPEOBJECT_CACHE.get_or_init` when it finds the lock taken.
            let initializer = scope.spawn(crate::typedef::init_typeobjects);
            // Takes the GIL in that window, then waits for the initializer.
            let sibling = scope.spawn(crate::typedef::init_typeobjects);
            // The first holder letting the GIL go is the initializer dropping
            // it at the contended lock; give the sibling a moment to take it
            // and reach its wait on the initializer before the lock is handed
            // over.
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
            let mut first_holder = 0;
            while std::time::Instant::now() < deadline {
                let holder = majit_gc::rgil::gil_get_holder();
                if first_holder == 0 {
                    first_holder = holder;
                } else if holder != first_holder {
                    break;
                }
                std::thread::sleep(std::time::Duration::from_millis(1));
            }
            std::thread::sleep(std::time::Duration::from_millis(200));
            release_tx.send(()).unwrap();
            initializer.join().unwrap();
            sibling.join().unwrap();
        });
    }

    /// Concurrent `init_typeobjects` callers must not observe the
    /// post-registration patch passes mid-write: the libtest harness
    /// calls it from many test threads, and an unsynchronized second
    /// caller used to probe `object`'s type dict while the first was
    /// still inserting `__class__` into it (IndexMap read/write race).
    /// Only the first init in the process has the race window, so this
    /// mainly guards the fix's `Once` barrier when scheduled early.
    #[test]
    fn init_typeobjects_races_no_corruption() {
        let threads: Vec<_> = (0..8)
            .map(|_| std::thread::spawn(crate::typedef::init_typeobjects))
            .collect();
        for t in threads {
            t.join()
                .expect("concurrent init_typeobjects must not panic");
        }
        // Also init on this thread: installs the thread-local hash hook the
        // dict probe below needs, and exercises the already-initialized path.
        crate::typedef::init_typeobjects();
        let object_type = crate::typedef::w_object();
        assert!(crate::type_dict_contains(object_type, "__class__"));
    }

